// guardedRoomRepository keeps Room's references whole; see guard.
type guardedRoomRepository struct {
	RoomRepository
	refs *repox.References
}

func (g *guardedRoomRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "searchdemo.v1/Room", name)
	if err != nil {
		return err
	}
	if err := g.RoomRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

